mapper.select:
SELECT DISTINCT p.PRODUCT_ID as productId, p.PRODUCT_NAME as productName, p.PRODUCT_TYPE as productType, p.PRICE as price, p.DEPOSIT as deposit, p.DESCRIPTION as description, p.IS_AVAILABLE as isAvailable, p.CREATED_AT as createdAt, p.CATEGORY_ID as categoryId, c.CATEGORY_NAME as categoryName, p.BRAND_ID as brandId, b.BRAND_NAME as brandName, i.IMG_URL as imgUrl FROM PRODUCT p LEFT JOIN PRODUCT_CATEGORY c ON p.CATEGORY_ID = c.CATEGORY_ID LEFT JOIN BRAND b ON p.BRAND_ID = b.BRAND_ID LEFT JOIN PRODUCT_IMG i ON p.PRODUCT_ID = i.PRODUCT_ID AND i.IS_MAIN = 'Y' WHERE 1=1 AND p.CATEGORY_ID = #{childCatId}
AND ( p.CATEGORY_ID = #{categoryId} OR p.CATEGORY_ID IN ( SELECT CATEGORY_ID FROM PRODUCT_CATEGORY WHERE PARENT_CATEGORY = #{categoryId} ) )
AND ( p.PRODUCT_NAME LIKE CONCAT('%', #{searchKeyword}, '%') OR b.BRAND_NAME LIKE CONCAT('%', #{searchKeyword}, '%') )
AND p.PRODUCT_TYPE = 'RENTAL'
AND p.PRODUCT_TYPE = 'PURCHASE'
AND 1 = 0
AND p.PRICE >= #{priceMin}
AND p.PRICE <= #{priceMax}
AND p.BRAND_ID IN #{id}

mapper.update:
UPDATE PRODUCT
SET VIEW_COUNT = VIEW_COUNT + 1
WHERE PRODUCT_ID = #{productId}
